// ===== 1. 定义判别联合：每个成员都有同名的字面量属性 status =====
type RequestState<T> =
  | { status: 'idle' }
  | { status: 'loading'; startedAt: number }
  | { status: 'success'; data: T; duration: number }
  | { status: 'error'; error: Error; retryCount: number };

// ===== 2. 配套的“创建工厂”，让非法状态无法被构造 =====
const Request = {
  idle: <T>(): RequestState<T> => ({ status: 'idle' }),
  loading: <T>(startedAt = Date.now()): RequestState<T> => ({ status: 'loading', startedAt }),
  success: <T>(data: T, duration: number): RequestState<T> => ({ status: 'success', data, duration }),
  fail: <T>(error: Error, retryCount: number): RequestState<T> => ({
    status: 'error', error, retryCount,
  }),
};

// ===== 3. 类型收窄 + 穷尽性检查 =====
function describe<T>(state: RequestState<T>): string {
  switch (state.status) {
    case 'idle':
      // 这里 state 被收窄为 { status: 'idle' }
      return '尚未发起请求';
    case 'loading':
      // 只有 loading 成员才拥有 startedAt
      return `加载中… 已耗时 ${Date.now() - state.startedAt}ms`;
    case 'success':
      // 只有 success 成员才拥有 data 与 duration
      return `成功：拿到 ${String(state.data).length} 个字符，耗时 ${state.duration}ms`;
    case 'error':
      // 只有 error 成员才拥有 error 与 retryCount
      return `失败（第 ${state.retryCount} 次重试）：${state.error.message}`;
    default: {
      // 穷尽性检查：新增分支却未处理时，这一行会在编译期报错
      const _exhaustive: never = state;
      return _exhaustive;
    }
  }
}

// ===== 4. 自定义类型守卫：在“无法自动收窄”的场景下手动收窄 =====
interface SuccessPayload { data: string }
interface ErrorPayload { reason: string }
type Payload = SuccessPayload | ErrorPayload;

function isSuccessPayload(p: Payload): p is SuccessPayload {
  return (p as SuccessPayload).data !== undefined;
}

// ===== 5. 运行验证 =====
const states: RequestState<string>[] = [
  Request.idle<string>(),
  Request.loading<string>(Date.now() - 800),
  Request.success<string>('hello typescript', 120),
  Request.fail<string>(new Error('网络超时'), 2),
];

for (const s of states) {
  console.log(describe(s));
}

const payload: Payload = { data: 'ok' };
if (isSuccessPayload(payload)) {
  console.log('收窄成功 ->', payload.data.toUpperCase());
}

